import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CQdiwDJy.js";const u=JSON.parse('{"title":"Terminal UI","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/tui.md","filePath":"en/guide/tui.md","lastUpdated":1788601681000}'),n={name:"en/guide/tui.md"};function s(r,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="terminal-ui" tabindex="-1">Terminal UI <a class="header-anchor" href="#terminal-ui" aria-label="Permalink to &quot;Terminal UI&quot;">​</a></h1><p><code>tau tui</code> is the full-keyboard terminal interface: the same engine, the same review gate, just rendered fullscreen.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tui</span></span></code></pre></div><h2 id="design-notes" tabindex="-1">Design notes <a class="header-anchor" href="#design-notes" aria-label="Permalink to &quot;Design notes&quot;">​</a></h2><ul><li><strong>Keyboard first</strong>: everything is reachable without a mouse; arrows/enter navigate, in-app help lists shortcuts.</li><li><strong>Slash command palette (v0.6.0)</strong>: typing <code>/</code> on an empty line opens a filterable command palette — keep typing to narrow, <code>↑</code>/<code>↓</code> to move, <code>Tab</code>/<code>Enter</code> to insert, <code>Esc</code> to dismiss; the palette, dispatch and <code>/help</code> share one command catalog, so what is shown can never drift from what runs.</li><li><strong>Model &amp; thinking selection (v0.6.2)</strong>: <code>/model</code> picks the provider&#39;s model from its live/cached catalog (interactive picker on a TTY, honest listing otherwise), <code>/thinking</code> shows or sets thinking mode and effort — both render exactly what the active provider supports, sharing the same catalog and config layer as the CLI and WebUI.</li><li><strong>ANSI rendering</strong>: plan explanations and results render as ANSI text through the shared markdown layer (<code>@tau/markdown</code> emits both HTML and ANSI from one abstraction).</li><li><strong>The same gate</strong>: the verdicts and confirmations you see in the TUI are identical to CLI and WebUI — it is not &quot;a looser mode&quot;.</li></ul><h2 id="when-the-tui-fits" tabindex="-1">When the TUI fits <a class="header-anchor" href="#when-the-tui-fits" aria-label="Permalink to &quot;When the TUI fits&quot;">​</a></h2><ul><li>Multi-turn conversations in the terminal without retyping <code>tau ask</code>;</li><li>Working over SSH with no browser;</li><li>Fullscreen focus without leaving the terminal.</li></ul><p>The three front doors divide by context: <strong>CLI</strong> for one-shots and pipes, <strong>TUI</strong> for immersive terminal work, <strong>WebUI</strong> for the richest visuals (thinking panels, tool cards, file viewer). The engine is one.</p>',8)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
